function maxProfit(prices: number[]): number {
  // Самая низкая цена среди уже прошедших дней — лучший день покупки
  let minPrice = Infinity;
  let best = 0;

  for (const price of prices) {
    if (price < minPrice) {
      // Нашли более дешёвый день для покупки
      minPrice = price;
    } else {
      // Пробуем продать сегодня, купив по минимальной цене в прошлом
      best = Math.max(best, price - minPrice);
    }
  }

  // Если цены только падали, best так и останется 0
  return best;
}

// Время: O(n) — один проход
// Память: O(1)
